/* ---------- installable app: offline helper, Android install button, iPhone tip ---------- */
const APP_ICONS = [["classic", "Crescent and Orion", "الهلال والجبار", "data:image/jpeg;base64,"], ["telescope", "Telescope", "التلسكوب", "data:image/jpeg;base64,"], ["compass", "Guiding star", "النجم الهادي", "data:image/jpeg;base64,"], ["planet", "Ringed planet", "الكوكب ذو الحلقات", "data:image/jpeg;base64,"], ["dipper", "Big Dipper", "بنات نعش", "data:image/jpeg;base64,"], ["crescent", "Crescent moon", "الهلال", "data:image/jpeg;base64,"], ["orbit", "Orbit", "المدار", "data:image/jpeg;base64,"], ["arch", "Desert window", "نافذة الصحراء", "data:image/jpeg;base64,"], ["galaxy", "Galaxy", "المجرة", "data:image/jpeg;base64,"], ["rose", "Compass rose", "وردة الرياح", "data:image/jpeg;base64,"], ["dome", "Night dome", "قبة الليل", "data:image/jpeg;base64,"], ["leo", "Constellation", "الكوكبة", "data:image/jpeg;base64,"], ["eclipse", "Dawn from space", "فجر من الفضاء", "data:image/jpeg;base64,"], ["astrolabe", "Astrolabe", "الأسطرلاب", "data:image/jpeg;base64,"], ["pleiades", "Seven Sisters", "الثريا", "data:image/jpeg;base64,"], ["desert", "Desert night", "ليل الصحراء", "data:image/jpeg;base64,"], ["starline", "Star-line S", "حرف S من النجوم", "data:image/jpeg;base64,"], ["globe", "Celestial globe", "الكرة السماوية", "data:image/jpeg;base64,"]];
const APP = (() => {
  const standalone = () => (window.matchMedia && matchMedia('(display-mode: standalone)').matches) || navigator.standalone === true;
  const ios = /iP(hone|ad|od)/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const android = /Android/i.test(navigator.userAgent);
  const safari = /Safari/.test(navigator.userAgent) && !/CriOS|FxiOS|EdgiOS|OPiOS|GSA\//.test(navigator.userAgent);
  let deferred = null;
  function toast(msg) {
    let t = document.getElementById('offtoast'); if (t) t.remove();
    t = document.createElement('div'); t.id = 'offtoast'; t.className = 'offtoast'; t.setAttribute('role', 'status'); t.setAttribute('dir', state.lang === 'ar' ? 'rtl' : 'ltr'); t.textContent = msg;
    document.body.appendChild(t); setTimeout(() => t.remove(), 4500);
  }
  // the offline helper runs only on the real site (not in previews or when opened as a file)
  if ('serviceWorker' in navigator && /^(yousef-ay12\.github\.io|localhost|127\.0\.0\.1)$/.test(location.hostname)) {
    addEventListener('load', () => { navigator.serviceWorker.register('sw.js').catch(() => {}); });
  }
  // Android and computers: Chrome tells the page when installing is possible
  addEventListener('beforeinstallprompt', ev => { ev.preventDefault(); deferred = ev; const b = document.getElementById('installbtn'); if (b) b.hidden = false; });
  addEventListener('appinstalled', () => { deferred = null; const b = document.getElementById('installbtn'); if (b) b.hidden = true; });
  document.addEventListener('click', ev => {
    if (ev.target.closest && ev.target.closest('#iconbtn')) { pick('change'); return; }
    if (ev.target.closest && ev.target.closest('#installbtn')) { if (deferred) pick('android'); else if (ios) pick('ios'); return; }
    if (ev.target.closest && ev.target.closest('[data-iconpick]')) pick(ios && safari ? 'ios' : deferred ? 'android' : 'info');
  });
  const getIcon = () => { try { return localStorage.getItem('osms-icon') || 'classic'; } catch (e) { return 'classic'; } };
  // the icon picker: choose how Sky Guide looks on your home screen, before installing
  function pick(mode) {
    const ar = state.lang === 'ar'; let sel = getIcon(); document.getElementById('iconpick') && document.getElementById('iconpick').remove();
    const box = document.createElement('div'); box.id = 'iconpick'; box.className = 'ipick'; box.setAttribute('dir', ar ? 'rtl' : 'ltr'); box.setAttribute('lang', ar ? 'ar' : 'en');
    const installed = standalone();
    const go = {android: ar ? 'ثبّت بهذه الأيقونة' : 'Install with this icon', ios: ar ? 'استخدم هذه الأيقونة' : 'Use this icon', info: ar ? 'احفظ اختياري' : 'Save my choice', change: ar ? 'استخدم هذه الأيقونة' : 'Use this icon'}[mode];
    box.innerHTML = `<div class="ip-in" role="dialog" aria-modal="true" aria-labelledby="ip-h"><div class="ip-top"><h3 id="ip-h">${ar ? 'اختر أيقونة التطبيق' : 'Choose your app icon'}</h3><button type="button" class="ip-x" aria-label="${ar ? 'إغلاق' : 'Close'}">✕</button></div>
      <p class="ip-sub">${mode === 'change' ? (ar ? 'اختر أيقونة جديدة لـ Sky Guide على شاشتك الرئيسية.' : 'Choose a new icon for Sky Guide on your home screen.') : installed ? (ar ? 'Sky Guide مثبّت بالفعل. لتغيير أيقونته: اختر أيقونة، ثم احذف التطبيق من الشاشة الرئيسية وأضفه مرة أخرى.' : 'Sky Guide is already installed. To change its icon: choose one, then remove the app from your home screen and add it again.') : (ar ? 'هذه الأيقونة ستظهر على شاشتك الرئيسية.' : 'This is how Sky Guide will look on your home screen.')}</p>
      <div class="ip-grid" role="radiogroup" aria-label="${ar ? 'الأيقونات' : 'Icons'}">${APP_ICONS.map(([id, en, a, src]) => `<button type="button" role="radio" class="ip-i" data-ic="${id}" aria-checked="${id === sel}"><img src="${src}" alt=""><span>${ar ? a : en}</span></button>`).join('')}</div>
      <div class="ip-go"><button type="button" class="pbtn main ip-ok">${go}</button></div></div>`;
    document.body.appendChild(box); document.documentElement.classList.add('ask-open');
    const close = () => { box.remove(); document.documentElement.classList.remove('ask-open'); };
    box.addEventListener('click', ev => { if (ev.target === box) close(); });
    box.querySelector('.ip-x').onclick = close;
    box.querySelectorAll('.ip-i').forEach(b => b.onclick = () => { sel = b.dataset.ic; box.querySelectorAll('.ip-i').forEach(x => x.setAttribute('aria-checked', x === b)); });
    box.querySelector('.ip-ok').onclick = async () => {
      try { localStorage.setItem('osms-icon', sel); } catch (e) {}
      const at = window.__iconAtLoad || 'classic';
      document.querySelector('link[rel=apple-touch-icon]').href = sel === 'classic' ? 'icons/apple-touch-icon.png' : `icons/choice/${sel}-180.png`;
      close();
      if (mode === 'android') {
        if (sel === at && deferred) { const d = deferred; deferred = null; document.getElementById('installbtn').hidden = true; try { await d.prompt(); } catch (e) {} }
        else { try { sessionStorage.setItem('osms-iconready', '1'); } catch (e) {} location.reload(); }
      } else if (mode === 'change') {
        // point the page at the matching app description, so Chrome sees the new icon when it next checks
        const mf = document.querySelector('link[rel=manifest]'); if (mf) mf.href = sel === 'classic' ? 'manifest.webmanifest' : `manifest-${sel}.webmanifest`;
        changed(sel);
      } else if (mode === 'ios') howto(sel);
      else toast(installed ? (ar ? 'تم الحفظ. احذف التطبيق من الشاشة الرئيسية وأضفه مرة أخرى لترى الأيقونة الجديدة.' : 'Saved. Remove the app from your home screen and add it again to see the new icon.') : (ar ? 'تم الحفظ. ستُستخدم هذه الأيقونة عندما تثبّت Sky Guide.' : 'Saved. This icon will be used when you install Sky Guide.'));
    };
    setTimeout(() => { const c = box.querySelector('.ip-i[aria-checked=true]') || box.querySelector('.ip-i'); c.focus(); c.scrollIntoView({block: 'nearest'}); }, 30);
  }
  // iPhone and iPad: show the Install button too; it leads to the icon picker, then these steps
  // Android, inside the installed app: a Change icon button
  // Android: a Change icon button once Sky Guide is installed. Inside the app it shows straight away; in Chrome it shows
  // when Chrome does not offer to install (which means it is already installed); it hides again if Chrome offers to install.
  const showIconBtn = on => { const b = document.getElementById('iconbtn'); if (b) b.hidden = !on; };
  if (android) {
    if (standalone()) addEventListener('DOMContentLoaded', () => showIconBtn(true));
    else addEventListener('load', () => setTimeout(() => { if (!deferred) showIconBtn(true); }, 3500));
    addEventListener('beforeinstallprompt', () => { if (!standalone()) showIconBtn(false); });
  }
  if (ios && !standalone()) addEventListener('DOMContentLoaded', () => { const b = document.getElementById('installbtn'); if (b) b.hidden = false; });
  function changed(sel) {
    const ar = state.lang === 'ar', ic = (APP_ICONS.find(x => x[0] === sel) || APP_ICONS[0]);
    const box = document.createElement('div'); box.id = 'iconpick'; box.className = 'ipick'; box.setAttribute('dir', ar ? 'rtl' : 'ltr'); box.setAttribute('lang', ar ? 'ar' : 'en');
    box.innerHTML = `<div class="ip-in" role="dialog" aria-modal="true" aria-labelledby="ip-h"><div class="ip-top"><h3 id="ip-h">${ar ? 'تم حفظ أيقونتك الجديدة' : 'Your new icon is saved'}</h3><button type="button" class="ip-x" aria-label="${ar ? 'إغلاق' : 'Close'}">✕</button></div>
      <div class="ip-how"><img src="${ic[3]}" alt=""><ol>
        <li>${ar ? 'سيعرض Chrome تحديث الأيقونة في المرة القادمة التي تفتح فيها Sky Guide، وغالبًا خلال يوم تقريبًا. اضغط «تحديث» عندما يسألك.' : 'Chrome will offer to update the icon the next time you open Sky Guide, usually within about a day. Tap “Update” when it asks.'}</li>
        <li>${ar ? 'تريدها الآن؟ احذف Sky Guide من شاشتك الرئيسية، ثم افتح الموقع في Chrome واضغط «ثبّت التطبيق». ستظهر أيقونتك الجديدة فورًا.' : 'Want it right now? Remove Sky Guide from your home screen, then open the site in Chrome and tap “Install app”. Your new icon appears straight away.'}</li></ol></div>
      <div class="ip-go"><button type="button" class="pbtn main ip-done">${ar ? 'حسنًا' : 'Got it'}</button></div></div>`;
    document.body.appendChild(box); document.documentElement.classList.add('ask-open');
    const close = () => { box.remove(); document.documentElement.classList.remove('ask-open'); };
    box.addEventListener('click', ev => { if (ev.target === box) close(); });
    box.querySelector('.ip-x').onclick = close; box.querySelector('.ip-done').onclick = close;
    setTimeout(() => box.querySelector('.ip-done').focus(), 30);
  }
  function howto(sel) {
    const ar = state.lang === 'ar', ic = (APP_ICONS.find(x => x[0] === sel) || APP_ICONS[0]), chrome = /CriOS/.test(navigator.userAgent), ipad = /iPad/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
    const where = chrome ? (ar ? 'في أعلى الشاشة بجانب شريط العنوان' : 'at the top, next to the address bar') : ipad ? (ar ? 'في أعلى الشاشة' : 'at the top of the screen') : (ar ? 'في أسفل الشاشة' : 'at the bottom of the screen');
    const box = document.createElement('div'); box.id = 'iconpick'; box.className = 'ipick'; box.setAttribute('dir', ar ? 'rtl' : 'ltr'); box.setAttribute('lang', ar ? 'ar' : 'en');
    box.innerHTML = `<div class="ip-in" role="dialog" aria-modal="true" aria-labelledby="ip-h"><div class="ip-top"><h3 id="ip-h">${ar ? 'أضف Sky Guide إلى شاشتك الرئيسية' : 'Add Sky Guide to your Home Screen'}</h3><button type="button" class="ip-x" aria-label="${ar ? 'إغلاق' : 'Close'}">✕</button></div>
      <div class="ip-how"><img src="${ic[3]}" alt=""><ol>
        <li>${ar ? `اضغط زر المشاركة <span class="ish">⬆︎</span> ${where}.` : `Tap the Share button <span class="ish">⬆︎</span> ${where}.`}</li>
        <li>${ar ? 'مرّر للأسفل واضغط «إضافة إلى الشاشة الرئيسية». قد تحتاج إلى الضغط على «المزيد» أولًا.' : 'Scroll down and tap “Add to Home Screen”. You may need to tap “More” or “View More” first.'}</li>
        <li>${ar ? 'اضغط «إضافة». ستظهر أيقونتك على الشاشة الرئيسية، ويفتح Sky Guide مثل التطبيق ويعمل دون إنترنت.' : 'Tap “Add”. Your icon appears on the Home Screen, and Sky Guide opens like an app and works offline.'}</li></ol></div>
      <div class="ip-go"><button type="button" class="pbtn" data-iconpick>${ar ? 'غيّر الأيقونة' : 'Change icon'}</button><button type="button" class="pbtn main ip-done">${ar ? 'حسنًا' : 'Got it'}</button></div></div>`;
    document.body.appendChild(box); document.documentElement.classList.add('ask-open');
    const close = () => { box.remove(); document.documentElement.classList.remove('ask-open'); };
    box.addEventListener('click', ev => { if (ev.target === box) close(); if (ev.target.closest('[data-iconpick]')) close(); });
    box.querySelector('.ip-x').onclick = close; box.querySelector('.ip-done').onclick = () => { try { localStorage.setItem('osms-install', 'seen'); } catch (e) {} const n = document.getElementById('installnote'); if (n) n.remove(); close(); };
    setTimeout(() => box.querySelector('.ip-done').focus(), 30);
  }
  // after the page reloads with the new icon, ask for one more tap to install
  addEventListener('load', () => { let r = null; try { r = sessionStorage.getItem('osms-iconready'); sessionStorage.removeItem('osms-iconready'); } catch (e) {}
    if (r) setTimeout(() => { toast(state.lang === 'ar' ? 'أيقونتك جاهزة. اضغط «ثبّت التطبيق» مرة أخرى لإكمال التثبيت.' : 'Your icon is ready. Tap “Install app” again to finish installing.'); const b = document.getElementById('installbtn'); if (b) b.classList.add('ip-pulse'); }, 900); });
  addEventListener('keydown', ev => { if (ev.key === 'Escape' && document.getElementById('iconpick')) { document.getElementById('iconpick').remove(); document.documentElement.classList.remove('ask-open'); } });
  // iPhone and iPad in Safari: a one-time tip, after the first-visit tour note is done
  function iosTip() {
    if (!ios || !safari || standalone() || document.getElementById('tournote') || document.getElementById('installnote')) return;
    let seen = true; try { seen = !localStorage.getItem('osms-tour') || !!localStorage.getItem('osms-install'); } catch (e) {}
    if (seen) return;
    const ar = state.lang === 'ar', n = document.createElement('div'); n.id = 'installnote'; n.className = 'tournote'; n.setAttribute('role', 'status'); n.setAttribute('dir', ar ? 'rtl' : 'ltr');
    n.innerHTML = ar ? `<b>أضف Sky Guide إلى الشاشة الرئيسية</b><span>اضغط زر المشاركة <span class="ish" aria-hidden="true">⬆︎</span> في Safari، ثم «إضافة إلى الشاشة الرئيسية». سيفتح مثل التطبيق ويعمل دون إنترنت.</span><div><button type="button" class="main">حسنًا</button> <button type="button" data-iconpick>اختر الأيقونة</button></div>`
                     : `<b>Add Sky Guide to your Home Screen</b><span>In Safari, tap Share <span class="ish" aria-hidden="true">⬆︎</span>, then “Add to Home Screen”. It opens like an app and works offline.</span><div><button type="button" class="main">Got it</button> <button type="button" data-iconpick>Choose the icon</button></div>`;
    n.querySelector('button.main').addEventListener('click', () => { try { localStorage.setItem('osms-install', 'seen'); } catch (e) {} n.remove(); });
    document.body.appendChild(n);
  }
  return {toast, iosTip, standalone, pick};
})();

